-- Safe to re-run: every statement is guarded (IF NOT EXISTS / OR REPLACE / DROP .. IF EXISTS).
--
-- DOWN:
--   DROP TABLE IF EXISTS collab_analysis_promotions, collab_analysis_artifacts, collab_analysis_requests;
--   DROP FUNCTION IF EXISTS collab_analysis_immutable();
-- Analysis coordination only: generated bytes remain verified room files.
CREATE TABLE IF NOT EXISTS collab_analysis_requests (
    request_id text PRIMARY KEY,
    room_id text NOT NULL REFERENCES collab_rooms(room_id) ON DELETE CASCADE,
    owner_id text NOT NULL REFERENCES collab_users(user_id) ON DELETE CASCADE,
    agent_id text NOT NULL REFERENCES collab_agents(agent_id) ON DELETE CASCADE,
    record jsonb NOT NULL CHECK (jsonb_typeof(record) = 'object')
);
CREATE INDEX IF NOT EXISTS collab_analysis_requests_room ON collab_analysis_requests(room_id);
CREATE TABLE IF NOT EXISTS collab_analysis_artifacts (
    artifact_id text PRIMARY KEY,
    request_id text NOT NULL UNIQUE REFERENCES collab_analysis_requests(request_id) ON DELETE CASCADE,
    record jsonb NOT NULL CHECK (jsonb_typeof(record) = 'object'),
    output_manifest jsonb NOT NULL CHECK (jsonb_typeof(output_manifest) = 'object')
);
CREATE TABLE IF NOT EXISTS collab_analysis_promotions (
    artifact_id text NOT NULL REFERENCES collab_analysis_artifacts(artifact_id) ON DELETE CASCADE,
    draft_id text NOT NULL UNIQUE REFERENCES collab_skill_drafts(draft_id) ON DELETE CASCADE,
    PRIMARY KEY (artifact_id, draft_id)
);
CREATE OR REPLACE FUNCTION collab_analysis_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'analysis provenance is immutable' USING ERRCODE = '23514';
END;
$$;
DROP TRIGGER IF EXISTS collab_analysis_request_immutable ON collab_analysis_requests;
CREATE TRIGGER collab_analysis_request_immutable BEFORE UPDATE ON collab_analysis_requests
    FOR EACH ROW EXECUTE FUNCTION collab_analysis_immutable();
DROP TRIGGER IF EXISTS collab_analysis_artifact_immutable ON collab_analysis_artifacts;
CREATE TRIGGER collab_analysis_artifact_immutable BEFORE UPDATE ON collab_analysis_artifacts
    FOR EACH ROW EXECUTE FUNCTION collab_analysis_immutable();
